mapper.select:
SELECT * FROM ( SELECT inner_query.*, ROWNUM AS rn FROM ( SELECT f.*, s.store_name, p.price FROM takku_funding f JOIN takku_store s ON f.store_id = s.store_id JOIN takku_product p ON f.product_id = p.product_id WHERE f.status IN ('진행중', '준비중')
AND f.funding_name LIKE '%' || #{keyword} || '%'
AND s.category_id = #{categoryId}
AND s.sido = #{sido}
AND s.sigungu = #{sigungu}
ORDER BY ( SELECT AVG(r.rating) FROM takku_review r JOIN takku_product p2 ON r.product_id = p2.product_id WHERE p2.product_id = f.product_id ) DESC NULLS LAST
ORDER BY f.end_date ASC
ORDER BY f.created_at DESC
) inner_query WHERE ROWNUM <= #{endRow} ) WHERE rn >= #{startRow}

SELECT COUNT(*)
FROM takku_funding f
JOIN takku_store s ON f.store_id =
s.store_id
WHERE f.status IN ('진행중', '준비중')

	AND f.funding_name LIKE '%' || #{keyword} || '%'


	AND s.category_id = #{categoryId}


	AND s.sido = #{sido}


	AND s.sigungu = #{sigungu}

mapper.update:
UPDATE
takku_funding SET status = #{status} WHERE end_date < SYSDATE AND
funding_id = #{fundingId}
